/**
 * Check if a string is a valid date in YYYY-MM-DD format.
 * @param {string} text
 * @returns {boolean}
 */
export function isValidDate(text) {
  const regex = /^\d{4}-\d{2}-\d{2}$/;
  if (!regex.test(text)) return false;
  const date = new Date(text + 'T00:00:00Z');
  const iso = date.toISOString().split('T')[0];
  return iso === text;
}

/**
 * Parse a YYYY-MM-DD date string into [year, month, day] (1-indexed month).
 * @param {string} dateStr
 * @returns {[number, number, number]}
 */
function parseDate(dateStr) {
  const [year, month, day] = dateStr.split('-').map(Number);
  return [year, month, day];
}

/**
 * Format [year, month, day] into YYYY-MM-DD string.
 * @param {number} year
 * @param {number} month
 * @param {number} day
 * @returns {string}
 */
function formatDate(year, month, day) {
  return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
}

/**
 * Add n days to a date string in YYYY-MM-DD format, using UTC.
 * @param {string} dateStr
 * @param {number} n
 * @returns {string}
 */
export function addDays(dateStr, n) {
  const date = new Date(dateStr + 'T00:00:00Z');
  date.setUTCDate(date.getUTCDate() + n);
  return date.toISOString().split('T')[0];
}

/**
 * Calculate the number of whole days between two dates (b - a), using UTC.
 * @param {string} a
 * @param {string} b
 * @returns {number}
 */
export function daysBetween(a, b) {
  const dateA = new Date(a + 'T00:00:00Z');
  const dateB = new Date(b + 'T00:00:00Z');
  const diffMs = dateB.getTime() - dateA.getTime();
  return Math.floor(diffMs / (1000 * 60 * 60 * 24));
}

